import 'package:flutter/material.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../theme/app_theme.dart';import 'withdraw.dart';
class WalletScreen extends StatefulWidget{const WalletScreen({super.key});@override State<WalletScreen>createState()=>_WalletState();}
class _WalletState extends State<WalletScreen>{Map<String,dynamic>? w;bool loading=true;Future<void>load()async{final u=Supabase.instance.client.auth.currentUser;if(u!=null)w=await Supabase.instance.client.from('wallets').select().eq('user_id',u.id).maybeSingle();if(mounted)setState(()=>loading=false);}@override void initState(){super.initState();load();}String m(dynamic v)=>double.tryParse('${v??0}')?.toStringAsFixed(2)??'0.00';@override Widget build(BuildContext c)=>SafeArea(child:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(18),children:[const Text('Wallet',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:15),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Available Balance',style:TextStyle(color:AppTheme.muted)),Text('৳${m(w?['available_balance'])}',style:const TextStyle(fontSize:32,fontWeight:FontWeight.w900)),Text('Total earned ৳${m(w?['total_earned'])}',style:const TextStyle(color:AppTheme.green)),const SizedBox(height:12),ElevatedButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const WithdrawScreen())),style:ElevatedButton.styleFrom(backgroundColor:AppTheme.green,foregroundColor:Colors.black),child:const Text('Withdraw'))])),const SizedBox(height:15),Card(child:Column(children:[ListTile(title:const Text('Pending'),trailing:Text('৳${'${m(w?['pending_amount'])}'}')),ListTile(title:const Text('Total withdrawn'),trailing:Text('৳${'${m(w?['total_withdrawn'])}'}')),if(loading)const LinearProgressIndicator()]))])));}
}
